/**
 * The discriminator for the different kinds of events an agent can emit while
 * responding to a request. Implementations may emit additional, custom event
 * types beyond the well-known ones enumerated here.
 */
export type AgentEventType =
  | 'stream_start'
  | 'stream_end'
  | 'message'
  | 'session_update'
  | 'elicitation_response'
  | (string & {});

/**
 * A single event emitted by an agent within a stream.
 *
 * Every event carries a unique {@link AgentEvent.id} and the
 * {@link AgentEvent.streamId} of the stream it belongs to, which allows callers
 * to resume streaming from an arbitrary point. Event-specific data is carried on
 * additional properties.
 */
export interface AgentEvent {
  /** The kind of event. */
  type: AgentEventType;
  /** A unique identifier for this event within the session. */
  id: string;
  /** The identifier of the stream this event belongs to. */
  streamId: string;
  /** Additional, event-specific payload. */
  [key: string]: unknown;
}

/**
 * The reason a stream ended, carried on a `stream_end` event.
 */
export type StreamEndReason = 'completed' | 'aborted' | (string & {});

/**
 * A partial event, as supplied to the mock's queueing helpers. The `id` and
 * `streamId` are filled in automatically when the event is committed to a
 * stream, so callers only need to provide the `type` and any event-specific
 * payload.
 */
export interface MockAgentEvent {
  /** The kind of event. */
  type: AgentEventType;
  /** An optional explicit id; one is generated when omitted. */
  id?: string;
  /** An optional explicit streamId; the target stream's id is used otherwise. */
  streamId?: string;
  /** Additional, event-specific payload. */
  [key: string]: unknown;
}

/**
 * A message being sent to the agent.
 */
export interface AgentSendMessage {
  type: 'message';
  [key: string]: unknown;
}

/**
 * A request to update the session's properties.
 */
export interface AgentSendUpdate {
  type: 'update';
  /** The properties to merge into the session state. */
  update?: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * A response to one or more outstanding elicitations.
 */
export interface AgentSendElicitations {
  type: 'elicitations';
  /** The individual elicitation responses. */
  elicitations?: Array<Record<string, unknown>>;
  [key: string]: unknown;
}

/**
 * A request to perform an action. Not every session supports actions.
 */
export interface AgentSendAction {
  type: 'action';
  /** The action to perform. */
  action?: { type?: string; [key: string]: unknown };
  [key: string]: unknown;
}

/**
 * The union of all payloads accepted by {@link AgentSession.send}.
 */
export type AgentSend =
  | AgentSendMessage
  | AgentSendUpdate
  | AgentSendElicitations
  | AgentSendAction;

